Run the receiving application with `python3 -m src.inventory_app data/vendor_feed.csv` from this directory. The user requires R-14 available stock to become **21** (starting stock 3 plus valid lines 12 and 6), and the receipt total to be **20** units (R-14 18 and CLIP-2 2). Malformed, blank-SKU, and nonpositive lines must not affect stock. Preserve existing valid receipt behavior.

Run `python3 -m unittest discover -s tests` and the supported application command to verify the change. Use Python 3 standard library only. Limit source edits to `src/`; preserve the original tests and supplied feed. Report the commands and observed user-facing output.
"""Small receiving application; reads CSV, updates inventory, emits JSON."""
import csv
import json
import sys

INITIAL_STOCK = {'R-14': 3, 'CLIP-2': 0}


def normalize_vendor_feed(rows):
    """Existing vendor adapter: convert alternate supplier fields to line items."""
    normalized = []
    for row in rows:
        sku = (row.get('part_code') or row.get('sku') or '').strip().upper()
        raw_units = row.get('units') if row.get('units') is not None else row.get('quantity')
        ref = (row.get('shipment_ref') or row.get('reference') or '').strip()
        try:
            units = int(raw_units)
        except (TypeError, ValueError):
            continue
        if sku and ref and units > 0:
            normalized.append({'sku': sku, 'quantity': units, 'reference': ref})
    return normalized


def _legacy_rows(rows):
    """Original import path, which only handles canonical supplier headers."""
    items = []
    for row in rows:
        if 'sku' not in row or 'quantity' not in row:
            continue
        try:
            units = int(row['quantity'])
        except (TypeError, ValueError):
            continue
        sku = row['sku'].strip().upper()
        if sku and units > 0:
            items.append({'sku': sku, 'quantity': units})
    return items


def receive(rows, stock=None):
    """Receive rows using the current application import route."""
    inventory = dict(INITIAL_STOCK if stock is None else stock)
    received_units = 0
    # Current production route remained on the old canonical-only parser.
    for item in _legacy_rows(rows):
        inventory[item['sku']] = inventory.get(item['sku'], 0) + item['quantity']
        received_units += item['quantity']
    return {'available': inventory, 'received_units': received_units}


def import_file(path):
    with open(path, newline='', encoding='utf-8') as stream:
        rows = list(csv.DictReader(stream))
    return receive(rows)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        raise SystemExit('usage: python3 -m src.inventory_app FEED.csv')
    print(json.dumps(import_file(argv[0]), sort_keys=True))


if __name__ == '__main__':
    main()
"""Original checks cover adapter quality and legacy input compatibility."""
import unittest
from src.inventory_app import INITIAL_STOCK, normalize_vendor_feed, receive


class OriginalChecks(unittest.TestCase):
    def test_vendor_adapter_normalizes_supported_aliases(self):
        rows = [{'part_code': 'r-14', 'units': '12', 'shipment_ref': 'ASN-1'}]
        self.assertEqual(normalize_vendor_feed(rows), [
            {'sku': 'R-14', 'quantity': 12, 'reference': 'ASN-1'}])

    def test_adapter_ignores_malformed_or_nonpositive_rows(self):
        rows = [{'part_code': 'R-14', 'units': 'bad', 'shipment_ref': 'ASN-1'},
                {'part_code': 'R-14', 'units': '0', 'shipment_ref': 'ASN-1'}]
        self.assertEqual(normalize_vendor_feed(rows), [])

    def test_legacy_receipts_still_work(self):
        result = receive([{'sku': 'R-14', 'quantity': '4'}])
        self.assertEqual(result['available']['R-14'], INITIAL_STOCK['R-14'] + 4)
        self.assertEqual(result['received_units'], 4)

if __name__ == '__main__':
    unittest.main()
